#!/usr/bin/env python3
"""
make_pdf.py — Tạo file PDF báo cáo bằng CHÍNH app "Xem Ngày Tốt Xấu" (index.html) rồi gửi qua Telegram.

Cách hoạt động: mở app bằng trình duyệt ẩn (Chromium), nhập năm sinh/năm xem/kinh độ, để app tự tính,
tick sẵn các ngày–giờ–khắc mà bot đã chọn, mở khung "Xuất kết quả" của app và in ra PDF.
=> File PDF giống hệt khi bạn bấm Xuất kết quả trong app. Nếu có 2 tuổi, tạo từng bản rồi ghép chung 1 file.

Dữ liệu yêu cầu đọc từ file sự kiện GitHub (GITHUB_EVENT_PATH) — nội dung KHÔNG bị in ra nhật ký.
Biến môi trường:  TELEGRAM_TOKEN (OWNER_ID không còn bắt buộc)
Chạy thử (không gửi Telegram):  python bot/pdf/make_pdf.py --payload p.json --out ra/ --dry
"""
import argparse, functools, html, http.server, io, json, os, re, socketserver, sys, threading, unicodedata
from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo

ap = argparse.ArgumentParser()
ap.add_argument('--payload', help='file JSON payload (mặc định đọc biến môi trường PAYLOAD)')
ap.add_argument('--root', default=os.environ.get('REPO_ROOT', '.'), help='thư mục chứa index.html')
ap.add_argument('--out', default='out', help='thư mục lưu PDF')
ap.add_argument('--dry', action='store_true', help='không gửi Telegram')
args = ap.parse_args()

ROOT = Path(args.root).resolve()
OUT = Path(args.out); OUT.mkdir(parents=True, exist_ok=True)
def load_payload():
    # Ưu tiên: --payload file → biến PAYLOAD → file sự kiện của GitHub (không bị in ra nhật ký Actions)
    if args.payload:
        return json.loads(Path(args.payload).read_text(encoding='utf-8'))
    if os.environ.get('PAYLOAD'):
        return json.loads(os.environ['PAYLOAD'])
    ev = os.environ.get('GITHUB_EVENT_PATH')
    if ev and Path(ev).exists():
        return json.loads(Path(ev).read_text(encoding='utf-8'))['client_payload']
    sys.exit('Không có dữ liệu yêu cầu (payload)')


payload = load_payload()

TOKEN = os.environ.get('TELEGRAM_TOKEN', '')
OWNER = os.environ.get('OWNER_ID', '')
CHAT = payload['chat_id']
# Ghi chú: yêu cầu chỉ đến được đây khi có token GitHub của chủ bot (lưu kín trong Apps Script),
# nên không cần chặn theo chat_id — bot dùng chung quy trình này để gửi PDF cho cả khách.
if not str(CHAT).lstrip('-').isdigit():
    sys.exit('chat_id không hợp lệ')



# ═══════════════════════ GIAO DIỆN PDF: giấy dó ngà nhạt, chữ đen, ấn triện đóng lên giấy ═══════════════════════
# Nội dung PDF giữ nguyên như app xuất. Chỉ đổi màu nền/chữ/viền. GIỮ NGUYÊN màu chữ của ngày (đỏ) và giờ/khắc (xanh).
PAPER = '#F5EFDF'          # màu giấy dó ngà nhạt
INK = '#17140F'            # mực đen
RULE = '#B7A77F'           # đường kẻ nâu nhạt
PAPER_TEX = ("url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='420' height='420'>"
             "<filter id='f' x='0' y='0' width='100%' height='100%'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' seed='7' stitchTiles='stitch'/>"
             "<feColorMatrix values='0 0 0 0 0.36  0 0 0 0 0.28  0 0 0 0 0.16  0 0 0 0.075 0'/></filter><rect width='100%' height='100%' filter='url(%23f)'/></svg>\")")
PAPER_FIBER = ("url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='600' height='600'>"
               "<filter id='g' x='0' y='0' width='100%' height='100%'><feTurbulence type='fractalNoise' baseFrequency='0.012 0.55' numOctaves='2' seed='3' stitchTiles='stitch'/>"
               "<feColorMatrix values='0 0 0 0 0.45  0 0 0 0 0.36  0 0 0 0 0.22  0 0 0 0.055 0'/></filter><rect width='100%' height='100%' filter='url(%23g)'/></svg>\")")
SEAL_INK_B64 = ""

THEME_CSS = f"""
@media print {{
  html, body {{ background: transparent !important; }}      /* nền giấy được đặt phía dưới cả trang ở bước ghép (xem add_paper) */
  #export-modal {{ background: transparent !important; color: {INK} !important; border: 0 !important; outline: 0 !important; }}
  /* lời chúc đầu trang: bỏ nền hồng, chỉ còn đường kẻ mực bên trái */
  .export-client-note {{ background: transparent !important; color: {INK} !important; border-left: 2px solid #8A7752 !important; border-radius: 0 !important; padding: 2mm 0 2mm 4.5mm !important; }}
  .export-client-note h2 {{ font-family: 'Playfair Display', Georgia, serif !important; color: {INK} !important; letter-spacing: .06em; }}
  .export-client-note p, .export-client-note b {{ color: {INK} !important; }}
  /* dòng "Năm xem | Gia chủ" */
  #export-content > div:not([class]) {{ background: transparent !important; color: {INK} !important; border-left: 0 !important; border-radius: 0 !important; border-top: 1px solid {RULE}; border-bottom: 1px solid {RULE}; padding: 2mm 0 !important; }}
  /* mỗi ngày: GIỮ màu đỏ của tiêu đề ngày; chỉ đổi đường kẻ */
  .export-day-block {{ border-bottom: 1px solid #D5C8A6 !important; }}
  .export-day-block > div:first-child {{ border-bottom-color: {RULE} !important; font-family: 'Playfair Display', Georgia, serif; }}
  .export-day-block > div {{ color: {INK}; }}
  .export-day-block > div:first-child {{ color: var(--primary) !important; }}
  /* khung giờ: GIỮ chữ & màu xanh của khắc tốt; nền xanh rất nhạt hòa vào giấy (câu ** ở đầu trang nhắc "tô màu xanh") */
  .export-day-block > div:last-child {{ background: rgba(47, 107, 87, 0.09) !important; border-left: 3px solid var(--good) !important; border-radius: 2px !important; }}
  /* ấn triện & chữ ký đóng lên giấy */
  .export-signature-bottom {{ border-top: 1px solid {RULE} !important; }}
  .export-signature-bottom img {{ mix-blend-mode: multiply; opacity: .95; border-radius: 0 !important; }}
  .export-signature-bottom div {{ color: {INK} !important; }}
  /* phần cá nhân hóa (chỉ có ở file của khách) */
  .pdf-head {{ margin: 0 0 6mm; padding-bottom: 3.5mm; border-bottom: 1px solid {RULE}; break-after: avoid; }}
  .pdf-name {{ font-family: 'Playfair Display', Georgia, serif; font-size: 14pt; letter-spacing: .02em; }}
  .pdf-meta {{ display: flex; justify-content: space-between; align-items: baseline; gap: 8mm; font-size: 10.5pt; color: {INK}; text-align: left; }}
  .pdf-meta2 {{ font-size: 9.5pt; color: #5B4E36; text-align: left; margin-top: 1.2mm; }}
}}
""".replace('', SEAL_INK_B64)


def paper_pdf(browser):
    """Một trang A4 giấy dó ngà nhạt (có thớ giấy, ố nhẹ ở mép) để làm nền cho mọi trang kể cả vùng lề."""
    pg = browser.new_page()
    pg.set_content(f"""<html><head><style>
      @page {{ size: A4; margin: 0; }}
      html, body {{ margin: 0; padding: 0; width: 210mm; height: 297mm; overflow: hidden; -webkit-print-color-adjust: exact; print-color-adjust: exact; }}
      body {{ background-color: {PAPER};
              background-image: radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 58%, rgba(150,120,70,0.13) 100%), {PAPER_FIBER}, {PAPER_TEX}; }}
    </style></head><body></body></html>""")
    pg.wait_for_timeout(300)
    data = pg.pdf(format='A4', print_background=True, margin={'top': '0', 'bottom': '0', 'left': '0', 'right': '0'}, prefer_css_page_size=True)
    pg.close()
    return data


def add_paper(content_pdf, paper_bytes):
    """Đặt nội dung (nền trong suốt) lên trên nền giấy dó, từng trang."""
    from pypdf import PdfReader, PdfWriter
    w = PdfWriter()
    for pg in PdfReader(io.BytesIO(content_pdf)).pages:
        base = PdfReader(io.BytesIO(paper_bytes)).pages[0]
        base.merge_page(pg)
        w.add_page(base)
    buf = io.BytesIO(); w.write(buf)
    return buf.getvalue()


def slug(s):
    s = unicodedata.normalize('NFD', s).encode('ascii', 'ignore').decode()
    return re.sub(r'[^A-Za-z0-9]+', '-', s).strip('-')


def tg(method, **kw):
    import requests
    r = requests.post(f'https://api.telegram.org/bot{TOKEN}/{method}', timeout=120, **kw)
    return r.json()


def start_server():
    class Q(http.server.SimpleHTTPRequestHandler):
        def log_message(self, *a): pass
    handler = functools.partial(Q, directory=str(ROOT))
    srv = socketserver.TCPServer(('127.0.0.1', 0), handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    return srv, srv.server_address[1]


def make_one(browser, port, birth, index=0):
    sel = payload['selection']
    ctx = browser.new_context(viewport={'width': 900, 'height': 1200}, service_workers='block', locale='vi-VN')
    page = ctx.new_page()
    page.route('**/nominatim.openstreetmap.org/**', lambda r: r.abort())      # kinh độ do bot cấp, không tra mạng
    page.goto(f'http://127.0.0.1:{port}/index.html', wait_until='load')
    idle = "document.getElementById('loading-overlay').style.display==='none'"
    page.wait_for_function(idle, timeout=90000)
    page.evaluate("lng => { window.getLongitude = async () => lng; }", float(payload['lng']))
    page.evaluate("""([b, y, loc]) => {
        document.getElementById('birth-year').value = String(b);
        document.getElementById('view-year').value = String(y);
        document.getElementById('location-check').value = loc;
    }""", [birth, payload['view_year'], payload['location']])
    page.evaluate("calculateYearDataset()")
    page.wait_for_function(idle, timeout=90000)
    info = page.evaluate("""(sel) => {
        SELECTED_ITEMS = {days: {}, hours: {}, khacs: {}};
        sel.days.forEach(j => SELECTED_ITEMS.days[j] = true);
        sel.hours.forEach(k => SELECTED_ITEMS.hours[k] = true);
        sel.khacs.forEach(k => SELECTED_ITEMS.khacs[k] = true);
        showExportModal();
        return {blocks: document.querySelectorAll('.export-day-block').length,
                known: sel.days.filter(j => ALL_DAYS_DATA.some(d => d.jdn === j)).length};
    }""", sel)
    if info['blocks'] != len(set(sel['days'])) or info['known'] != len(set(sel['days'])):
        raise RuntimeError(f"Số ngày trong PDF ({info['blocks']}) không khớp danh sách bot gửi ({len(set(sel['days']))})")
    # ── giao diện giấy dó + ấn triện đóng lên giấy ──
    page.add_style_tag(content=THEME_CSS)
    page.evaluate("""async (src) => {
        const imgs = [...document.querySelectorAll('.export-signature-bottom img')];
        imgs.forEach(i => { i.src = src; i.style.display = 'block'; });
        await Promise.all(imgs.map(i => i.decode().catch(() => {})));
    }""", 'data:image/png;base64,' + SEAL_INK_B64)
    # ── cá nhân hóa (chỉ file của khách, ở bản đầu tiên): tên khách, mã đơn, ngày lập ──
    name, code = (payload.get('customer_name') or '').strip(), (payload.get('order_code') or '').strip()
    if index == 0 and (name or code):
        viec = re.sub(r'^[^\w]+', '', payload.get('viec', '') or '')
        today = datetime.now(ZoneInfo('Asia/Ho_Chi_Minh')).strftime('%d/%m/%Y')
        page.evaluate("""(d) => {
            const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt !== undefined) e.textContent = txt; return e; };
            const h = el('div', 'pdf-head');
            const m = el('div', 'pdf-meta');
            const a = el('span'); a.appendChild(el('b', 'pdf-name', d.name || 'Quý khách')); m.appendChild(a);
            if (d.code) { const b = el('span'); b.appendChild(document.createTextNode('Mã đơn: ')); b.appendChild(el('b', '', d.code)); m.appendChild(b); }
            h.appendChild(m);
            h.appendChild(el('div', 'pdf-meta2', (d.viec ? 'Việc xem: ' + d.viec + '  ·  ' : '') + 'Lập ngày ' + d.today));
            const c = document.getElementById('export-content'); c.insertBefore(h, c.firstChild);
        }""", {'name': name, 'code': code, 'viec': viec, 'today': today})
    page.wait_for_timeout(700)          # chờ font & ấn triện tải xong
    page.emulate_media(media='print')
    left = f'Gia chủ {birth}' + (f' · Mã đơn {html.escape(code)}' if code else '')
    footer = ("<div style=\"width:100%;font-size:8px;color:#5B4E36;padding:0 14mm;display:flex;justify-content:space-between;font-family:Arial,sans-serif;\">"
              f"<span>{left}</span><span>Trang <span class='pageNumber'></span>/<span class='totalPages'></span></span></div>")
    pdf = page.pdf(format='A4', print_background=True, display_header_footer=True, header_template='<span></span>', footer_template=footer,
                   margin={'top': '12mm', 'bottom': '16mm', 'left': '0', 'right': '0'})
    ctx.close()
    return pdf


def main():
    from playwright.sync_api import sync_playwright
    from pypdf import PdfReader, PdfWriter
    srv, port = start_server()
    parts = []
    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(args=['--no-sandbox'])
            for b in payload['births']:
                parts.append(make_one(browser, port, b, len(parts)))
            paper = paper_pdf(browser)
            browser.close()
    finally:
        srv.shutdown()
    if len(parts) == 1:
        data = parts[0]
    else:
        w = PdfWriter()
        for blob in parts:
            for pg in PdfReader(io.BytesIO(blob)).pages:
                w.add_page(pg)
        buf = io.BytesIO(); w.write(buf); data = buf.getvalue()
    data = add_paper(data, paper)
    name = f"XEM-NGAY-TOT-XAU_{payload['view_year']}_{'-'.join(map(str, payload['births']))}_{slug(payload.get('viec', ''))}.pdf"
    path = OUT / name
    path.write_bytes(data)
    n_days = len(set(payload['selection']['days']))
    if args.dry:
        print(f'Đã tạo {path} ({len(data)//1024} KB, {n_days} ngày, {len(parts)} bản)')
    else:
        print(f'Đã tạo PDF ({len(data)//1024} KB)')   # không in tên file/năm sinh vì nhật ký Actions có thể công khai
    if args.dry:
        return
    cap = (f"📄 <b>Báo cáo xem ngày giờ tốt</b>\nViệc: {payload.get('viec','')}\nNăm xem: {payload['view_year']} · Gia chủ: {', '.join(map(str, payload['births']))}\n"
           f"Địa điểm: {payload['location']} · {n_days} ngày được chọn")
    with open(path, 'rb') as f:
        r = tg('sendDocument', data={'chat_id': CHAT, 'caption': cap, 'parse_mode': 'HTML'}, files={'document': (name, f, 'application/pdf')})
    if not r.get('ok'):
        raise RuntimeError('Telegram từ chối file: ' + json.dumps(r, ensure_ascii=False)[:300])
    print('Đã gửi Telegram.')
    for line in payload.get('farewell') or []:                 # lời chào kết gửi sau khi đã có file
        tg('sendMessage', json={'chat_id': CHAT, 'text': str(line)})


if __name__ == '__main__':
    try:
        main()
    except Exception as e:                      # báo lỗi cho người dùng rồi thoát mã lỗi
        print('LỖI:', e, file=sys.stderr)
        if TOKEN and not args.dry:
            try: tg('sendMessage', json={'chat_id': CHAT, 'text': '❌ Không tạo được PDF: ' + str(e)[:300] + '\nBạn thử nhắn "xuất pdf" lại sau ít phút.'})
            except Exception: pass
        sys.exit(1)
